{"results": [{"id": "hp_doc_860f25fdb12f9231cec8579c78dc8ef982c4e2ce3864260ef36f27da7c8cc299", "title": "Debbie (song)", "text": "\"Debbie\" is the lead single from the compilation album \"\" by The B-52's. The song was inspired by Debbie Harry of the band Blondie. The single's music video was directed by Ramaa Mosley.", "score": 29.0588}, {"id": "hp_doc_2bfb510b407a02b5137000774c252c99d3008d083b2b249944d425f2096a7d3a", "title": "Union City Blue", "text": "\"Union City Blue\" is a song by the US rock band Blondie. It was written by Debbie Harry and Nigel Harrison, and was featured on their fourth studio album \"Eat to the Beat\" from 1979. The tune was inspired by the 1979 movie \"Union City\", which Debbie Harry appeared in (she wrote the lyrics one evening during a break in the shooting).", "score": 25.1418}, {"id": "hp_doc_66b8be872822a82e593281eb52e2237e8b53348ee2320663a0e07152aa214d57", "title": "Atomic (song)", "text": "\"Atomic\" is a hit song by the American new wave band Blondie, written by Debbie Harry and Jimmy Destri and produced by Mike Chapman. It was released as the third single from the band's Platinum-selling 1979 album \"Eat to the Beat\".", "score": 18.5647}], "remaining_searches": 2}
